// src/components/BudgetLimits.js
import React, { useState, useEffect } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ formData }) {
  const [limits, setLimits] = useState({});

  // Compute categories dynamically from current formData
  const categories =
    formData &&
    formData.spendingPriority
      ? Object.keys(formData.spendingPriority).filter(
          (cat) => formData.spendingPriority[cat] >= 3
        )
      : [];

  // Initialize limits for categories
  useEffect(() => {
    if (categories.length) {
      const initialLimits = {};
      categories.forEach((cat) => {
        initialLimits[cat] = formData.budgetLimits?.[cat] || 0;
      });
      setLimits(initialLimits);
    }
  }, [categories, formData]);

  const handleChange = (category, value) => {
    setLimits((prev) => ({
      ...prev,
      [category]: Number(value),
    }));
  };

  const handleSave = async () => {
    if (!categories.length) {
      alert("No categories selected for budgeting.");
      return;
    }

    const finalData = {
      incomeType: formData.incomeType || "No Income",
      category: formData.category || "No Income",
      questionnaire: formData.questionnaire || {},
      spendingPriority: formData.spendingPriority || {},
      budgetLimits: limits,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const res = await fetch("http://localhost:5000/api/userdata/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(finalData),
      });

      const data = await res.json();
      if (data.success) alert("Limits saved successfully!");
      else alert("Failed to save data");
    } catch (err) {
      console.error(err);
      alert("Server connection failed");
    }
  };

  return (
    <div className="budget-container">
      <h2 className="budget-title">Set Monthly Budget Limits</h2>
      {categories.length ? (
        <div className="budget-grid">
          {categories.map((cat) => (
            <div key={cat} className="budget-card">
              <h3 className="budget-name">{cat}</h3>
              <input
                type="number"
                min={0}
                value={limits[cat] || 0}
                onChange={(e) => handleChange(cat, e.target.value)}
                className="budget-input"
              />
            </div>
          ))}
        </div>
      ) : (
        <p style={{ color: "red" }}>
          No categories selected with priority ≥ 3
        </p>
      )}
      <button onClick={handleSave} className="save-button">
        Save Budget
      </button>
    </div>
  );
}

export default BudgetLimits;
